        selected_profile::paid::validate(context, function, &mut measured)
            .map_err(|e| detailed(function, e))
            .unwrap();
        let used = measured.physical.as_deref().unwrap().charged();
        let mut exact = ReplayBudget::with_physical(function, used).unwrap();
        selected_profile::paid::validate(context, function, &mut exact).unwrap();
        assert_eq!(exact.physical.as_deref().unwrap().charged(), used);
        let mut short = ReplayBudget::with_physical(function, used - 1).unwrap();
        assert!(selected_profile::paid::validate(context, function, &mut short).is_err());

        use crate::cleanup_plan::replay::inventory_coverage::paid::validate_inventory_coverage;
        let mut measured = ReplayBudget::with_physical(function, usize::MAX).unwrap();
        validate_inventory_coverage(context, function, &mut measured)
            .map_err(|e| detailed(function, e))
            .unwrap();
        let used = measured.physical.as_deref().unwrap().charged();
        let mut exact = ReplayBudget::with_physical(function, used).unwrap();
        validate_inventory_coverage(context, function, &mut exact).unwrap();
        assert_eq!(exact.physical.as_deref().unwrap().charged(), used);
        let mut short = ReplayBudget::with_physical(function, used - 1).unwrap();
        assert!(validate_inventory_coverage(context, function, &mut short).is_err());

        use crate::cleanup_plan::replay::{collect_leaves_paid, structural_maps};
        let mut ordinary_budget = ReplayBudget::unobserved();
        let ordinary = collect_leaves_paid(function, &mut ordinary_budget).unwrap();
        let mut measured = ReplayBudget::with_physical(function, usize::MAX).unwrap();
        let indexed = structural_maps::paid::iterator_leaves(function, &mut measured).unwrap();
        assert_eq!(ordinary.len(), indexed.len());
        for ((flag, leaf), (expected_flag, expected)) in indexed.iter().zip(ordinary.iter()) {
            assert_eq!(
                (flag, &leaf.place, &leaf.lifecycle),
                (expected_flag, &expected.place, &expected.lifecycle)
            );
        }
        let used = measured.physical.as_deref().unwrap().charged();
        let mut exact = ReplayBudget::with_physical(function, used).unwrap();
        assert!(structural_maps::paid::iterator_leaves(function, &mut exact).is_ok());
        assert_eq!(exact.physical.as_deref().unwrap().charged(), used);
        let mut short = ReplayBudget::with_physical(function, used - 1).unwrap();
        assert!(structural_maps::paid::iterator_leaves(function, &mut short).is_err());
        let mut closed = ReplayBudget::with_physical(function, usize::MAX).unwrap();
        assert!(structural_maps::paid::leaves(function, &mut closed).is_err());

        let mut budget = ReplayBudget::with_physical(function, usize::MAX).unwrap();
        let held =
            selected_context::Context::new_paid(context, function, &mut budget, true).unwrap();
        let facts = expression_facts::paid_arena(function, &mut budget).unwrap();
        let storage = structural_maps::paid::slots(function, &mut budget).unwrap();
        crate::cleanup_plan::replay::structural_control::selected::validate_blocks_and_edges_paid(
            &held,
            function,
            &facts,
            &storage,
            &indexed,
            held.primitive_renewals(function).unwrap(),
            &mut budget,
        )
        .map_err(|e| detailed(function, e))
        .unwrap();

        use crate::cleanup_plan::replay::{expected_exit_regions, lexical_hir, structural_control};
        use crate::hir::LexicalExitKind;
        let lexical = lexical_hir::collect(function, &mut budget).unwrap();
        let operands = lexical
            .exits
            .iter()
            .filter(|exit| exit.kind == LexicalExitKind::Return)
            .filter_map(|exit| exit.value.map(|operand| operand.id.clone()))
            .collect();
        let check_exits = |f: &ResolvedFunction, budget: &mut ReplayBudget| {
            structural_control::selected::validate_exits(
                &held, f, &storage, &indexed, &operands, budget,
            )
        };
        let mut measured = ReplayBudget::with_physical(function, usize::MAX).unwrap();
        check_exits(function, &mut measured)
            .map_err(|e| detailed(function, e))
            .unwrap();
        let used = measured.physical.as_deref().unwrap().charged();
        let mut exact = ReplayBudget::with_physical(function, used).unwrap();
        check_exits(function, &mut exact).unwrap();
        assert_eq!(exact.physical.as_deref().unwrap().charged(), used);
        let mut short = ReplayBudget::with_physical(function, used - 1).unwrap();
        assert!(check_exits(function, &mut short).is_err());

        let continue_id = function
            .cleanup_plan
            .lexical_control
            .as_ref()
            .unwrap()
            .exits
            .iter()
            .find(|exit| exit.kind == LexicalExitKind::Continue)
            .expect("authored iterator continue")
            .exit;
        let mut forged = function.clone();
        let exit = &mut forged.cleanup_plan.exits[continue_id.0 as usize];
        assert_eq!(
            expected_exit_regions(function, exit).unwrap(),
            exit.leaves_regions
        );
        let last = exit.leaves_regions.last().expect("continue leaves scratch");
        let retained = function.cleanup_plan.regions[last.0 as usize]
            .parent
            .unwrap();
        exit.leaves_regions.push(retained);
        let mut budget = ReplayBudget::with_physical(&forged, usize::MAX).unwrap();
        let error = check_exits(&forged, &mut budget).unwrap_err();
        assert!(detailed(&forged, error)
            .message
            .contains("exact source-to-target region chain"));

        let mut forged = function.clone();
        let action = forged
            .cleanup_plan
            .exits
            .iter_mut()
            .flat_map(|exit| &mut exit.finalize_in_order)
            .find(|action| action.active_case.is_some())
            .expect("case-qualified iterator finalizer");
        action.active_case = None;
        let mut budget = ReplayBudget::with_physical(&forged, usize::MAX).unwrap();
        let error = check_exits(&forged, &mut budget).unwrap_err();
        assert!(detailed(&forged, error)
            .message
            .contains("exact variant case path"));

        let mut forged = function.clone();
        let flag = forged
            .cleanup
            .flags
            .iter_mut()
            .find(|flag| flag.place.projections.len() == 2)
            .expect("case-qualified iterator flag");
        flag.place.projections.swap(0, 1);
        let mut budget = ReplayBudget::with_physical(&forged, usize::MAX).unwrap();
        assert!(validate_inventory_coverage(context, &forged, &mut budget).is_err());

        let mut forged = function.clone();
        let slot = forged
            .cleanup_plan
            .slots
            .iter_mut()
            .find(|slot| {
                matches!(
                    slot.storage,
                    crate::cleanup_plan::StorageId::CallArgument { .. }
                ) && crate::iterator_ops::is_iter(&slot.ty)
            })
            .expect("owned iterator argument slot");
        slot.field_liveness_shape = crate::cleanup::FieldLivenessShape::NoDrop;
        let mut budget = ReplayBudget::with_physical(&forged, usize::MAX).unwrap();
        assert!(validate_inventory_coverage(context, &forged, &mut budget).is_err());

        for attack in 0..3 {
            let mut hostile = function.clone();
            let ResolvedExprKind::Block { statements, .. } = &mut hostile.body.kind else {
                panic!("function block");
            };
            let inner = statements
                .iter_mut()
                .find_map(|statement| {
                    let ResolvedStatement::Let { value, .. } = statement else {
                        return None;
                    };
                    let ResolvedExprKind::Block { statements, .. } = &mut value.kind else {
                        return None;
                    };
                    matches!(
                        statements.last(),
                        Some(ResolvedStatement::LexicalWhile { .. })
                    )
                    .then_some(statements)
                })
                .expect("owning wrapper");
            let [ResolvedStatement::Let { value: seed, .. }, ResolvedStatement::LexicalWhile {
                condition, latch, ..
            }] = inner.as_mut_slice()
            else {
                panic!("lowered seed and loop");
            };
            match attack {
                0 => {
                    let LoopLatchKind::OwnedIteratorStep {
                        next, assignment, ..
                    } = latch
                    else {
                        panic!("owned latch");
                    };
                    *next = assignment.clone();
                }
                1 => {
                    let ResolvedExprKind::Call { args, .. } = &mut seed.kind else {
                        panic!("iterator seed");
                    };
                    args[0].ownership = OwnershipMode::Borrow;
                }
                2 => {
                    let ResolvedExprKind::Match { arms, .. } = &mut condition.kind else {
                        panic!("iterator condition");
                    };
                    let crate::hir::ResolvedMatchPattern::Variant { fields, .. } =
                        &mut arms[1].pattern
                    else {
                        panic!("yielded fields");
                    };
                    fields.swap(0, 1);
                }
                _ => unreachable!(),
            }
            let mut budget = ReplayBudget::with_physical(&hostile, usize::MAX).unwrap();
            assert!(selected_profile::paid::validate(context, &hostile, &mut budget).is_err());
        }
    });
}

